"""The code every new peg starts from, and the guide that comes with it.

Two commands create a peg's interface, ``workpeg project create`` and
``workpeg ui new``, and until now each wrote its own: one a single page that
subclassed ``Scaffold``, the other a counter and a page of ASCII art laid out
with a hand-written style dict. A coding agent opening either project copied
what it found, so the first thing it learned was the opposite of how a peg is
meant to look.

Both now write the same starter from ``templates/starter/``: a ``Router``
whose pages sit under the ``/b/[business_id]`` shell, an ``AppShell`` that
returns the SDK ``Scaffold``, shared state Components, and a list page and a
detail page that draw every state a data view has. Beside it they write
``AGENTS.md``, the guide an agent reads before it changes anything, and a
one-line ``CLAUDE.md`` that imports it.

The guide is never overwritten. A repository often has its own ``AGENTS.md``
or ``CLAUDE.md`` already, and ``--force`` is how a person writes a starter
into a folder that has files in it; replacing their guide with ours would be
silent data loss. So an existing file is kept, always, and the caller is told
which ones were.
"""
from __future__ import annotations

import shutil
from importlib import resources
from pathlib import Path

#: Substituted through every template file. A single token rather than a
#: templating language: the scaffold is a handful of small files, and a
#: dependency for that would cost more than it saves.
PLACEHOLDER = "REPLACE_NAMESPACE"

#: The guide's files, in the order a person is told about them.
GUIDE_FILES = ("AGENTS.md", "CLAUDE.md")


class TemplateExists(Exception):
    """A template file would overwrite one that is already there."""


def _template(name: str):
    return resources.files("workpeg") / "templates" / name


def copy_template(source: Path, target: Path, namespace: str, *,
                  force: bool) -> list[Path]:
    """Copy *source* into *target*, replacing the placeholder in text files.

    Returns the files written, relative to *target*. Without *force*, a file
    that already exists stops the copy before it is touched.
    """
    written = []
    for item in sorted(source.rglob("*")):
        if "__pycache__" in item.parts or item.suffix == ".pyc":
            continue
        rel = item.relative_to(source)
        dest = target / rel
        if item.is_dir():
            dest.mkdir(parents=True, exist_ok=True)
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.exists() and not force:
            raise TemplateExists(f"{dest} already exists.")
        # Text files carry the placeholder; anything binary is copied as-is.
        # Decided by trying to read it rather than by extension, so a template
        # gaining a .png does not need this function to be told about it.
        try:
            body = item.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            shutil.copy2(item, dest)
        else:
            dest.write_text(body.replace(PLACEHOLDER, namespace),
                            encoding="utf-8")
        written.append(rel)
    return written


def starter_files() -> list[str]:
    """The starter's files, relative and in POSIX form, sorted."""
    with resources.as_file(_template("starter")) as root:
        root = Path(root)
        return sorted(
            p.relative_to(root).as_posix() for p in root.rglob("*")
            if p.is_file() and "__pycache__" not in p.parts
            and p.suffix != ".pyc")


def write_starter(target: Path, namespace: str, *, force: bool) -> list[Path]:
    """Write the Scaffold starter into *target*, the folder for ``main.py``."""
    with resources.as_file(_template("starter")) as root:
        return copy_template(Path(root), Path(target), namespace, force=force)


def write_agent_guide(target: Path,
                      namespace: str) -> tuple[list[str], list[str]]:
    """Write ``AGENTS.md`` and ``CLAUDE.md`` into *target*.

    Returns ``(written, kept)``: the names written, and the names left alone
    because a file of that name was already there. Never overwrites, whatever
    the caller's ``--force`` said.
    """
    target = Path(target)
    target.mkdir(parents=True, exist_ok=True)
    written, kept = [], []
    with resources.as_file(_template("agents")) as root:
        for name in GUIDE_FILES:
            dest = target / name
            if dest.exists():
                kept.append(name)
                continue
            body = (Path(root) / name).read_text(encoding="utf-8")
            dest.write_text(body.replace(PLACEHOLDER, namespace),
                            encoding="utf-8")
            written.append(name)
    return written, kept
